#!/usr/bin/env python3
"""Exact-clean-source1800s soak wrapper. Preparation is never soak acceptance."""
import argparse,datetime,hashlib,importlib.util,json,os,platform,re,signal,sys,time
from pathlib import Path
sys.dont_write_bytecode=True
HERE=Path(__file__).resolve().parent
HELPER_SHA='509106d70e5e35c1142594c98df022b01e689966415bdd94a8f67feecb8587d8'
helper=HERE/'owned_delivery_helper.py'
if hashlib.sha256(helper.read_bytes()).hexdigest()!=HELPER_SHA:raise RuntimeError('reviewed helper identity mismatch')
spec=importlib.util.spec_from_file_location('soak_owned_helper',helper);D=importlib.util.module_from_spec(spec);spec.loader.exec_module(D)
SECONDS=1800
WINDOW=60
MAX_LOG=4*1024*1024
def utc():return datetime.datetime.now(datetime.timezone.utc).isoformat()
def command(argv,cwd,env,log,timeout,records):
    args=[str(x) for x in argv];started=time.monotonic();record={'argv':args,'argv_sha256':hashlib.sha256(json.dumps(args,separators=(',',':'),ensure_ascii=True).encode()).hexdigest(),'started_utc':utc(),'timeout_seconds':timeout,'log':log.name};records.append(record)
    try:return D.run(args,cwd=cwd,env=env,timeout=timeout,limit=MAX_LOG,log_path=log)
    finally:
        record.update({'elapsed_seconds':time.monotonic()-started,'finished_utc':utc()})
        if log.is_file():record['log_sha256']=D.digest(log)
def machine():
    info={'os':platform.platform(),'system':platform.system(),'machine':platform.machine(),'cpu_count':os.cpu_count(),'python':platform.python_version(),'cpu_model':platform.processor(),'ram_bytes':None}
    if platform.system()=='Darwin':
        info['cpu_model']=D.run(['sysctl','-n','machdep.cpu.brand_string'],limit=65536).decode().strip();info['ram_bytes']=int(D.run(['sysctl','-n','hw.memsize'],limit=65536))
    elif hasattr(os,'sysconf'):
        info['ram_bytes']=os.sysconf('SC_PHYS_PAGES')*os.sysconf('SC_PAGE_SIZE')
        cpu=Path('/proc/cpuinfo')
        if cpu.is_file():
            with cpu.open('rb') as stream:raw=stream.read(1048576).decode(errors='replace')
            for line in raw.splitlines():
                if line.startswith('model name') and ':' in line:info['cpu_model']=line.split(':',1)[1].strip();break
    D.require(type(info['ram_bytes']) is int and info['ram_bytes']>0,'RAM metadata unavailable');return info
def validate_history(path,sha):
    D.require(path.is_file() and path.stat().st_size<=1048576,'fresh history output missing/budget');lines=path.read_text().splitlines();D.require(lines[0]=='# zee-soak-gecmisi-1','history schema');rows=[x.split('\t') for x in lines if x and not x.startswith('#')];D.require(len(rows)==1,'exact one fresh history row');r=rows[0];D.require(len(r)==17 and r[0]==sha and r[3].startswith('rustc 1.93.1 ') and r[4:6]==['1800','60'] and r[14:17]==['10','32768','gecti'],'source/duration/threshold/result history');D.require(all(int(r[x])>0 for x in (6,7,8,9,10,11)),'actual periods/RSS missing');return r
def perform(repo,sha,out,source_hashes):
    D.clean_exact(repo,sha);out.mkdir(mode=0o700);records=[];runner_pins={'runner':D.digest(Path(__file__).resolve()),'owned_helper':D.digest(helper)};proof={'schema':'zee-exact-clean-soak-wrapper-1','source_sha':sha,'status':'running','acceptance':False,'seconds':SECONDS,'window_seconds':WINDOW,'threshold_percent':10,'threshold_kib':32768,'threshold_operator':'both-exceeded','helper_sha256':HELPER_SHA,'source_helpers':source_hashes,'external_runner_start_sha256':runner_pins,'commands':records,'started_utc':utc()}
    try:
        proof['machine']=machine();clone=out/'source';D.clone(repo,clone,sha);D.clean_exact(clone,sha)
        env=D.controlled_env();env.update({'CARGO_NET_OFFLINE':'true','CARGO_TARGET_DIR':str(out/'target'),'RUSTUP_TOOLCHAIN':'1.93.1','RUSTC_WRAPPER':'','RUSTC_WORKSPACE_WRAPPER':'','RUSTFLAGS':'','CARGO_ENCODED_RUSTFLAGS':''});env.pop('CARGO_BUILD_TARGET',None)
        for key in list(env):
            if key.startswith('CARGO_PROFILE_'):env.pop(key)
        rustc_path=D.run(['rustup','which','--toolchain','1.93.1','rustc'],limit=65536).decode().strip();D.require(Path(rustc_path).is_file(),'installed pinned rustc path');env['RUSTC']=rustc_path
        rustc=D.run([rustc_path,'--version'],env=env,limit=65536).decode().strip();D.require(rustc.startswith('rustc 1.93.1 '),'actual Rust version');proof['toolchain']={'rustc':rustc,'rustc_vV':D.run([rustc_path,'-vV'],env=env,limit=65536).decode(),'cargo':D.run(['cargo','+1.93.1','--version'],env=env,limit=65536).decode().strip(),'profile':'release','offline':True,'rustflags':'empty','source_date_epoch':env.get('SOURCE_DATE_EPOCH')}
        command(['cargo','+1.93.1','build','--locked','--offline','--release','--bin','dillsp','--bin','soak'],clone/'compiler',env,out/'build.log',3600,records);D.clean_exact(clone,sha)
        binaries={name:out/'target/release'/name for name in ('dillsp','soak')};pins={name:D.digest(p) for name,p in binaries.items()};proof['binary_start_sha256']=pins
        history=out/'soak-history.tsv';report=out/'soak-report.md';D.require(not history.exists() and not report.exists(),'fresh external history/report')
        started=time.monotonic();command([binaries['soak'],'--sure-sn','1800','--pencere-sn','60','--dillsp',binaries['dillsp'],'--gecmis',history,'--rapor',report],clone/'compiler',env,out/'soak.log',2100,records);elapsed=time.monotonic()-started;D.require(elapsed>=1800,'actual monotonic minimum1800')
        row=validate_history(history,sha);D.require(report.is_file() and 0<report.stat().st_size<=1048576,'report output bound');D.clean_exact(clone,sha);D.clean_exact(repo,sha)
        final={name:D.digest(p) for name,p in binaries.items()};D.require(final==pins,'binary changed during soak');D.require({x:D.digest(repo/x) for x in source_hashes}==source_hashes,'source helper changed');external_final={'runner':D.digest(Path(__file__).resolve()),'owned_helper':D.digest(helper)};D.require(external_final==runner_pins,'external runner/helper changed');proof['external_runner_end_sha256']=external_final;proof.update({'status':'passed','acceptance':True,'actual_elapsed_seconds':elapsed,'binary_end_sha256':final,'history_row':row,'history_sha256':D.digest(history),'report_sha256':D.digest(report),'source_end_clean':True,'source_end_sha':D.git(clone,'rev-parse','HEAD')})
    except BaseException as e:proof['status']='failed';proof['acceptance']=False;proof['failure_type']=type(e).__name__;raise
    finally:
        proof['finished_utc']=utc();(out/'PROOF.json').write_text(json.dumps(proof,indent=2)+'\n')
    return proof
def main(argv=None):
    p=argparse.ArgumentParser();p.add_argument('--repo',type=Path,required=True);p.add_argument('--sha',required=True);p.add_argument('--out',type=Path,required=True);p.add_argument('--preflight-only',action='store_true');a=p.parse_args(argv)
    D.CANCELLED=False
    def cancelled(number,frame):D.CANCELLED=True
    for n in (signal.SIGINT,signal.SIGTERM):signal.signal(n,cancelled)
    repo,out,hashes=D.preflight(a.repo,a.sha,a.out)
    for rel in ('compiler/src/bin/soak.rs','compiler/src/bin/dillsp.rs','compiler/Cargo.lock','compiler/Cargo.toml'):
        D.require((repo/rel).is_file(),'required soak source missing');hashes[rel]=D.digest(repo/rel)
    if a.preflight_only:D.clean_exact(repo,a.sha);print(json.dumps({'status':'preflight-passed','source_sha':a.sha,'acceptance':False,'build_or_soak_executed':False}));return 0
    proof=perform(repo,a.sha,out,hashes);print(json.dumps({'status':proof['status'],'acceptance':proof['acceptance'],'source_sha':a.sha}));return 0
if __name__=='__main__':
    try:raise SystemExit(main())
    except (D.Reject,OSError,ValueError) as e:print(json.dumps({'status':'rejected','type':type(e).__name__}),file=sys.stderr);raise SystemExit(2)
